import os
import sys

def close_all_applications():
  for app in os.listdir(os.path.expanduser("~") + "/Applications"):
    if os.path.isfile(os.path.expanduser("~") + "/Applications/" + app):
      os.system("killall " + app)

if __name__ == "__main__":
  close_all_applications()
